-- Non-sensitive schema proof only. No buyer, credential, payment or order rows.
SELECT jsonb_build_object(
 'relations',(SELECT jsonb_object_agg(c.relname,jsonb_build_object('owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,
 'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',p.polname,'roles',(SELECT jsonb_agg(pg_get_userbyid(role_oid)ORDER BY pg_get_userbyid(role_oid))FROM unnest(p.polroles)role_oid),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid))ORDER BY p.polname),'[]'::jsonb)FROM pg_policy p WHERE p.polrelid=c.oid),
 'columns',(SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',(SELECT pg_get_expr(d.adbin,d.adrelid)FROM pg_attrdef d WHERE d.adrelid=a.attrelid AND d.adnum=a.attnum))ORDER BY a.attnum)FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT coalesce(jsonb_object_agg(k.conname,jsonb_build_object('definition',pg_get_constraintdef(k.oid),'validated',k.convalidated)),'{}'::jsonb)FROM pg_constraint k WHERE k.conrelid=c.oid)))FROM pg_class c WHERE c.oid IN('saas.platform_checkout281_predecessors'::regclass,'saas.platform_checkout_orders'::regclass,'saas.platform_checkout_intents'::regclass,'saas.platform_checkout_attempts'::regclass,'saas.platform_checkout_audit'::regclass)),
 'receiptExtension',jsonb_build_object('columns',(SELECT jsonb_object_agg(a.attname,jsonb_build_object('type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull))FROM pg_attribute a WHERE a.attrelid='saas.store_tool_receipts'::regclass AND a.attname IN('operator_id','checkout_order_id')AND NOT a.attisdropped),'constraints',(SELECT jsonb_object_agg(k.conname,jsonb_build_object('definition',pg_get_constraintdef(k.oid),'validated',k.convalidated))FROM pg_constraint k WHERE k.conrelid='saas.store_tool_receipts'::regclass AND k.conname IN('store_tool_receipt_actor281','store_tool_receipt_checkout281'))),
 'indexes',(SELECT jsonb_object_agg(c.relname,jsonb_build_object('definition',pg_get_indexdef(c.oid),'unique',i.indisunique,'valid',i.indisvalid,'ready',i.indisready))FROM pg_class c JOIN pg_index i ON i.indexrelid=c.oid WHERE c.oid IN('saas.platform_checkout_one_active_attempt281'::regclass,'saas.platform_checkout_proof281'::regclass,'saas.platform_checkout_store281'::regclass)),
 'triggers',(SELECT jsonb_object_agg(t.tgname,jsonb_build_object('definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled,'type',t.tgtype,'function',t.tgfoid::regprocedure::text,'internal',t.tgisinternal))FROM pg_trigger t WHERE t.tgname IN('platform_checkout_orders_guard281','platform_checkout_intents_guard281','platform_checkout_attempts_guard281','platform_checkout_audit_immutable281','store_tool_receipt_validate281'))
);
